chapters=[];scenes=[]
def ch(n,title,seq,boundary,pressure):chapters.append(dict(chapter=n,title=title,sequence=f'S{seq:02}',boundary_reason=boundary,scenes=[],end_pressure=pressure))
def sc(n,day,start,end,place,cast,before,goal,obstacle,decision,events,cost,next_cause,knowledge,resources,setup,guard,unknowns=()):
    c=chapters[n-1];i=len(c['scenes'])+1;sid=f'B04-CH{n:02}-SC{i:02}';kid=f'K{len(scenes)+1:02}'
    previous=scenes[-1]['id'] if scenes else None
    s=dict(id=sid,chapter=n,sequence=c['sequence'],status='planned_proposed_implementation',pov='Марк Даль, перша особа, минулий час',time=dict(day=f'D{day}',start=start,end=end,basis='proposed scene placement, not observed prose clock'),place=place,cast=cast.split('/'),state_before=before,goal=goal,obstacle=obstacle,decision=decision,events=events,result=events,cost=cost,next_cause=next_cause,knowledge_in=[before],knowledge_out=[kid+': '+knowledge],resources_permissions=resources,setup_payoff=setup,execution_guard=guard,state_before_source=dict(carry='carry-in-source-lock.json',previous_planned_scene=previous,rule='Попередня подія обмежує стан, але не передає знання відсутнім людям.'),voices={x:VOICES.get(x,'Окремий предметний голос без всезнання.') for x in cast.split('/')},dependencies=dict(knowledge=[previous] if previous else ['carry-in-source-lock.json'],working_decisions=['D01','D02','D03','D04','D05','D06'],unknowns=list(unknowns)),chapter_end_pressure=c['end_pressure'])
    scenes.append(s);c['scenes'].append(sid)

ch(1,'Чий ліміт',1,'Виконати стару умовну домовленість новим підтвердженням, а не почати з повтору порівняння двох файлів.','Едіт готова показати власне житлове повідомлення; нове поле ще не пояснює її випадок.')
sc(1,0,'08:30','12:30','Квартира Даля → крамниця','Даль/Власниця крамниці','Фінал попереднього тому — субота. Понеділок 11:00 лише запропоновано; гроші обмежені, постійної роботи немає.','Отримати певний обсяг і заробити, не віддати ранок новому запиту.','Власниця не підтверджувала ні обсягу, ні ставки; новий лист із сервісу спокушає кинути побут.','Дочекатися ранкового підтвердження обсягу/оплати, погодити й виконати одну звірку ярликів.','Власниця повідомляє про готовий обмежений список і ту саму ставку за обсяг; Даль підтверджує 11:00. На місці не бере додаткової полиці без домовленості, здає роботу й отримує оплату. Лист про бюджет читає після неї.','Втрачає кілька годин для швидкої відповіді, натомість не має права назвати разовий платіж стабільним доходом.','Після роботи може прочитати відповідь, не спираючись на чужий скасований доступ.','Понеділкова пропозиція стала однією виконаною угодою тільки в цій сцені.','Звичайний доступ; власний пристрій, жодного поновлення професії. Оплата показана фактом надходження без нового канонічного тарифу.','C03: виплата умовного понеділка; P05: компетентність існує без статусу.','Не пересувати фінал Book3 на неділю; дві календарні межі до понеділка. Ося тут відсутній і чужі файли не відкриті.',['U04'])
sc(1,0,'13:30','14:30','Читальня','Даль/Тарас','Новий суб’єктний запит зареєстровано в суботу без обіцяного строку. Збережено тільки дозволений знеособлений рядок порівняння.','Зрозуміти джерело власного ресурсного ліміту.','Відповідь неповна: містить застосовану групу координаційних витрат, але не всі ваги й приватні входи.','Перевірити номер/версію/вікно, відділити власне пояснення від Осиного та надіслати лише коротку звістку про рядок.','Надходить відповідь на суботній номер: інституційна група сумісності впливає на межі підтримки поруч із ризиком і політикою програми. Даль бачить власну високу групу, не доказ її людського значення. Ося отримує повідомлення про походження поля без повернення архіву. Тарас телефоном передає дозволене прохання Едіт, давньої клієнтки ремонту; власного повідомлення вона не пересилала через нього. Даль погоджується на її завтрашній час.','Не отримує повної причини різниці двох старих чисел; приємна висока власна оцінка штовхає його обіцяти забагато.','Особистий запит Едіт дає законну причину бачити окремий випадок застосування тієї самої метрики.','Координаційні дані — один upstream чинник; точна історична декомпозиція двох лімітів невідома. Тарас знає тільки передане прохання.','Власна відповідь; Осині уривки лишаються відкликаними. Один погоджений контакт Едіт, не доступ до її справи.','P01: новий доказ до називання механізму; P05: висока група лестить.','Не стверджувати однакову uncertainty, витрачені бюджети чи критерій вартості людини. Це нова відповідь, не виконання старого обіцяного дедлайну.',['U-BUDGET','U-PRIVATE'])

ch(2,'Тут',1,'Побачити житло й волю Едіт перед відкриттям справи.','Заяву прийнято на D14; відповідальний оцінювач — Рем Ковач.')
sc(2,1,'10:00','11:15','Квартира Едіт у кооперативному будинку','Даль/Едіт','Едіт сама запросила Даля. У нього немає її історії, лише адреса.','З’ясувати, що вона хоче зберегти.','Даль шукає ознаки несправедливо забутої корисності; вона сердиться на огляд квартири як музей заслуг.','Спитати про конкретне повідомлення і прочитати тільки те, що вона подає.','Едіт відсуває чашки з підвіконня, щоб відкрити вікно, відмовляється пояснювати кожну річ. Повідомлення стосується поновлення автономного проживання з людською підтримкою, а не позбавлення власності. Житло/база гарантовані; стандартна альтернатива має задані вікна й менше власного розкладу. Вона хоче цю квартиру, своїх сусідів і можливість не планувати кожен вихід.','Даль бачить, що виграш у кращій новій кімнаті не рівнозначний її бажанню.','Потрібно подати заперечення до чинного рішення.','Даль і читач довідуються про поновлення програми та позицію Едіт; її професія автоматизована, прихованого таланту не заявлено.','До остаточного розгляду поточне проживання збережене; нові документи показані особисто, без побутового прослуховування.','P02/P06: дім — теперішня потреба, не нагорода за минулу працю.','Не перетворювати жінку на медичний ризик або виставку самотності. Даль не знає, що вона відчуває без її слів.')
sc(2,1,'13:00','14:10','Сервісна приймальня кооперативної програми','Даль/Едіт/Працівниця приймальні','Едіт хоче оскаржити поновлення; право подати є без високого бала. Даль має тільки старий професійний запис.','Зареєструвати апеляцію й зупинити адміністративне завершення до слухання.','Форма просить представника й обсяг доступу; Даль тягнеться заповнити її професійним титулом.','Увійти як дозволений помічник, долучивши перевірюваний старий досвід без заяви про чинний допуск.','Едіт власноруч подає заяву. Приймальня підтверджує D14 10:00, чинність теперішнього проживання до рішення й право змінити маршрут заявки до D13 12:00. Даль отримує лише її пакет; старий запис дає можливість перевірити кваліфікацію для окремої ролі згодом, не привілейоване право подання. Ім’я оцінювача — Рем Ковач — змінює його тон.','Він обіцяє знайти помилку в оцінці раніше, ніж знає дані; Едіт віддає час власним документам.','Рем призначає зустріч із матеріалами оцінки.','Дата, право доповнення й hold отримані тут; Даль впізнає колишнього рівного, не сучасного таємного керівника.','Обмежене представництво до закриття справи/відкликання. Старе професійне право OFF.','P05: титул у полі форми; P02: поспішна обіцянка спростувати.','Не поновлювати калибрувальний доступ. Заявник не мусить знати високостатусного друга, щоб апеляцію взагалі прийняли.')

ch(3,'Колишній рівний',2,'Особисте суперництво впирається в правдиві дані.','Замість викриття помилки Рем пропонує дієвий план стабільності.')
sc(3,2,'09:30','11:00','Кабінет оцінювання; видимий робочий коридор','Даль/Едіт/Рем','Даль пам’ятає Рема колегою; Едіт дозволила обговорити тільки її погодження.','Виявити помилку, що скасує негативне поновлення.','Рем показує два підтверджені перенесення й пропущений узгоджений доступ для загальнобудинкових робіт; не всі витрати вигадані.','Перевірити знаменник, добровільність зобов’язань і відокремити виправну неточність від решти.','Рем виправляє одну дубльовану позначку без бою, але загальна оцінка істотно не змінюється. Едіт визнає один пропуск і заперечує вимогу бути на зв’язку весь день. Рем показує час повторного виїзду, резерв працівника й confidence, визнає: модель не знає, скільки вона варта. Даль не здобуває очікуваної перемоги.','Виправлення справжньої помилки не дає квартири; Даль мусить відмовитися від красивої однієї причини.','План стабільності може знизити виміряні витрати до попереднього порога.','Балл стосується координації й невизначеності, не інтелекту/доброти. Високі витрати частково підтверджені.','Особисті документи Едіт, знеособлені години кооперативу; жодних інших профілів.','P02/P04: опонент визнає локальну помилку й лишається сильним.','Не робити всі скасовані необов’язкові зустрічі порушенням договору; лише явно взяті зобов’язання входять до фактичного зриву.')

ch(4,'Тимчасово',2,'Привабливий шлях має справжню користь й умови; K-17 з’являється людиною до свого програшу.','Едіт погоджується на коротку пробу; Даль береться довести, що метод працює.')
sc(4,2,'11:10','11:40','Коридор приймальні','Даль/Едіт/Кирило','Після оцінювання чекають видачі умов. Інші особисті справи їм закриті.','Не пропустити виклик, поки Едіт відходить по воду.','Кирило з номером K-17 не може одночасно донести пакунок і стежити за мінливим табло.','Притримати пакунок і назвати побачений номер, не читати чужу теку.','Кирило сам називається, забирає пакунок із гострим соусом; питає, де тут реальна людина для зміни вікна. Каже, що хоче день без трьох розірваних очікувань. Його викликають раніше, розмова обривається; контактів і дозволу на справу ще немає.','Едіт мусить нагадати Далю про власний виклик; увага героя обмежена вже зараз.','Видиме очікування надає ваги пропозиції одного передбачуваного вікна.','K-17 — номер звернення Кирила, не клас неповноцінності; його біографія й подробиці невідомі.','Чужа текa закрита; допомога з пакунком не дорівнює представництву.','P07: людина до статистики; пляшка соусу пізніше має звичайне побутове продовження.','Ім’я Кирило — запропонована локальна реалізація, не авторська цитата. Не ототожнювати з Левом майбутнього тому.',['U-K17'])
sc(4,2,'12:00','13:00','Кімната погодження','Даль/Едіт/Рем','Фактичний cost частково високий; теперішнє житло захищене до D14.','Знайти шлях зберегти квартиру до завершення апеляції.','Стандартний план обіцяє швидкість, але вимагає передбачуваного дня; Едіт не хоче постійного компаньйона.','Погодити пробу D3–D7 з одним вікном зв’язку, ручними підтвердженнями та правом припинення.','Рем пояснює план і звичайний Тихий контур без погрози базовим правам. Едіт обирає ручні підказки у власному пристрої, не обов’язковий домашній нагляд. Даль бере на себе допомогу з формулюваннями, переконує, що п’ять днів дадуть шанс. Рем письмово відділяє попередню оцінку від кінцевого рішення.','Едіт платить самонаглядом за можливість лишитися; Даль пов’язує успіх зі зростанням бала.','Перше реальне погодження має відбутися завтра.','Проба не гарантує поновлення; відмова не позбавляє безпечної бази й права апеляції.','Письмові межі на п’ять днів; домашні сенсори й чужі приватні повідомлення не передаються.','P03: користь і добровільність під обмеженим вибором.','Не ритуалізувати кожну натиснуту кнопку; один ясний обсяг, потім прожитий наслідок.')

ch(5,'Вікно відповіді',3,'Реальний ремонт показує, чому взаємні зобов’язання не суцільний обман.','Успіх одного вікна спокушає Даля поширити метод на весь день Едіт.')
sc(5,3,'09:00','10:15','Під’їзд і квартира Едіт','Даль/Едіт/Неля','Завтра потрібен доступ до стояка; минулого разу майстер їхав двічі.','Домовитися про необхідні роботи без цілоденного очікування.','Едіт не розуміла, які сусіди залежать від її відповіді; Неля не може тримати майстра весь день.','Вибрати одне реальне вікно й запасний спосіб попередження про зміну.','Неля показує загальну схему робіт без інших приватних даних. Едіт обирає 09:00–10:00 наступного дня, сама підтверджує. Даль допомагає скоротити форму, не обіцяє її постійну доступність.','Едіт переносить власний ранковий похід; Неля резервує оплачений час, який не можна видати вдруге.','Тепер треба виконати, а не лише красиво підтвердити.','Одна спільна залежність з’ясована; не кожна незручність — напад на автономію.','Одногодинне вікно доступу; звичайний ключ у власниці житлового права, без віддаленого відкриття Баластом.','P02/P03: необхідна взаємність, що згодом лишиться в manual plan.','Не вигадувати аварійну загрозу життю; це планове обслуговування.')
sc(5,3,'18:00','18:40','Квартира Даля','Даль/Баласт','Одне підтвердження отримано, виконання завтра. Компаньйон у ручному режимі.','Зробити власний список допомоги й строків.','Баласт може оптимізувати лише те, що Даль ввів, а герой прагне готового способу поліпшити всю справу.','Вручну відкрити сервіс і дати власні часові зобов’язання та знеособлені типи форм.','Баласт пропонує шаблони короткого підтвердження й підготовки спору. Даль зберігає їх, не завантажує справу Едіт; вона окремо бачить запропоновані тексти наступного дня. Він додає надлишкові власні нагадування, відчуваючи повернення вправності.','Вільний вечір стає підготовкою чужої поведінки; нове розширення ще не дозволене.','Успішний ранковий ремонт дасть Далю підставу нав’язати шаблон на зборах.','Баласт знає лише введені строки/форми, не Едіт як особу.','Сесійний ручний текст; home/mic OFF, жодних автономних відповідей.','P05: майстерність повертається як спокуса.','Не поновлювати зручний день Book3 за замовчуванням; чернетка інструмента не наказ.')

ch(6,'Коротший протокол',3,'Реальний виграш у часі співіснує з втраченим питанням.','Підтверджені виконання покращують індикатор; загублене питання не зникає.')
sc(6,4,'09:00','11:30','Квартира → спільна кімната кооперативу','Даль/Едіт/Неля','Є вчорашня домовленість, зборам потрібен той самий ранок; підготовлений шаблон Едіт погодилась спробувати.','Виконати ремонт і донести заперечення щодо нового режиму спільної кімнати.','Ремонт завершується вчасно, а на зборах усі втомилися; шаблон перетворює її заперечення на прохання уточнити.','Даль допомагає закрити стислий протокол, обіцяючи повернути питання окремо.','Майстер входить у погоджене вікно й виконує роботу. На зборах Едіт читає пом’якшений текст про вечірнє закриття кімнати; секретар записує лише уточнення часу. Неля економить пів години, але заперечення проти нового порядку не розглянуто. Едіт помічає пропуск; Даль відкладає виправлення до кінця проби.','Її реальний вибір не потрапляє до рішення; відкладення створює обов’язок повернутися до нього в CH28.','Рем бачить менше повторних погоджень і пропонує закріпити успіх.','Результативна координація не доводить повноти представленої волі; спірне правило не стало бажанням Едіт.','Роботу сплачено з чинного обслуговування; протокол доступний учасникам, сторонні дані не відкрито.','P03; P09: власне заперечення Едіт у протоколі, payoff CH28 без гарантованої перемоги.','Не називати шаблон mind control: вона може заперечити, але боїться втратити результат.')

ch(7,'Попередньо',3,'Відокремити виміряний короткий ефект від довгого права лишитися.','Рем пропонує перевірити Даля для тимчасової ролі супроводу.')
sc(7,4,'15:00','16:10','Кооперативний стіл обслуговування','Даль/Едіт/Рем','Два виконані зобов’язання й коротший протокол; фінального права ще немає.','Отримати підтвердження прогресу.','Кількох днів недостатньо для стійкості; без відповідального за підтримку план крихкий.','Просити попередню оцінку, а Далеву кваліфікацію подати на окрему перевірку.','Рем показує покращення з широкою невизначеністю й умовністю щодо збереження підтримки. Едіт питає, коли перестане рахувати кожну відповідь. Даль називає D14, не маючи обіцянки, що тоді режим закінчиться. Рем видає перелік нової sponsor-сертифікації; Даль погоджується вивчити.','Його стара репутація робиться ресурсом, який хочеться знову мати.','Завтра перевірка здатності нести нові конкретні зобов’язання.','Видимий приріст — короткостроковий і умовний; чинного sponsor немає.','Тільки заява на сертифікацію; матеріали старого стажу перевіряються без робочих інструментів.','P03/P05: слово попередньо захищає причинність.','Не зробити п’ять днів доведенням незмінної особистості чи вже завершеною пробою.')

ch(8,'Новий пропуск',4,'Спокуса статусу має практичну швидкість і нову договірну ціну.','Даль отримує вузький пропуск, що хочеться використати ширше за справу Едіт.')
sc(8,5,'10:00','11:30','Суботня приймальня програми','Даль/Рем','Новий сертифікаційний огляд призначено окремо; старі калібрувальні права закриті.','Отримати канал відповідального супроводу для апеляції.','Рем перевіряє реальний стаж і теперішню доступність; Даль хоче, щоб старого імені вистачило.','Прийняти лише строкову роль до D15 18:00 з двома щоденними check-in, власним планом і межами справи.','Даль проходить перевірку форм і пояснює, як передасть чергування, якщо не зможе прийти. Рем прямо відрізняє нову роль від операторського допуску. Даль вмикає у Баласта тільки власні нагадування про check-in, вручну вводить необхідні строки; домашній доступ і чужий файл не потрібні. Пропуск відкриває службовий стіл цієї справи, не місто.','Зобов’язання займають його власні вікна заробітку; старий комфорт повертається за нову регулярну працю.','Треба виконати перше коротке погодження й відчути реальну перевагу.','Роль надана тепер, на строк і предмет; висока стара група лише один доказ досвіду.','Sponsorship: читання дозволеної справи, передача форм, канал приймальні; без калібрування/медичних прав.','P05: статус подобається не тільки з марнославства, а через корисність.','Не представляти суботні години універсальним законом усіх установ; це призначене вікно цієї програми.')
sc(8,5,'12:00','12:45','Робочий стіл приймальні → вулиця','Даль/Едіт','Новий пропуск чинний, але рішення ради ще немає.','Усунути технічну помилку форми, що затримує пакет.','У звичайній черзі це зайняло б повторний візит; новий канал дозволяє одразу зв’язатися з відповідальним.','Скористатися вузьким каналом і передати виправлену форму на перевірку Едіт.','Помилкову дубльовану позначку з CH3 остаточно прибирають із пакета. Едіт отримує квитанцію; Даль проходить через службові двері з приємною звичною швидкістю. Вона не святкує пропуск, а питає, чи завтра може піти на ринок без запису.','Він затримує відповідь, бо вже думає про дані стабільності, а не про її вихідний.','Спроба поширити простий метод на Осю проявить його власний інтерес.','Роль знижує адміністративне тертя; це не доказ людської вищості.','Дублікат виправлений, оригінальне спостереження збережене в історії; лише Едіт затверджує свій пакет.','P04/P05: перевага каналу реальна, а не самонавіювання.','Не розголошувати її оцінку стороннім і не наділяти пропуск правом командувати її виходами.')

ch(9,'Без поліпшення',4,'Ося переносить здобуте авторство в новий тиск, а не проходить третій том повторно.','Відмова Оси позбавляє Даля зручного алібі: не кожне підвищення бала є допомогою.')
sc(9,6,'10:00','11:00','Пункт повернення тари → вуличний перехід','Даль/Ося','Після одного пробного рейсу постійної роботи не встановлено. Ося сам обрав нове окреме оплачуване доручення й прийшов по тару.','Даль хоче спростити Осі наступні погодження.','Розклад іншого замовлення рухомий; Ося не просив ані оцінки, ані представництва.','Запропонувати шаблон один раз і прийняти відмову без прихованого застосування.','Ося показує тільки час власного нового доручення, не score. Даль починає рахувати, як стабільні вікна зробили б профіль привабливішим, і чує коротке ні: рейс уже погоджено, а ще одна форма забирає час на нього. Ося іде на оплачуване завдання сам; Даль не вписує його до sponsor-пакета.','Даль пропускає зручний момент похвалитися статусом; ніякої нової гарантії Осиного працевлаштування немає.','Наступне схвалення Едіт мусить бути перевірене її власним днем.','Даль знає лише показані умови доручення; актуальний бал Оси невідомий і не виводиться з Book3 uncertainty.','Новий окремий робочий контракт належить Осі. Немає обміну даними/спільного sponsor ризику без згоди.','P05: ближні не розширення власного рейтингу.','Не стверджувати, що старий sponsor уже захищає права Оси або Тараса; такі права ніколи не були його ресурсом.',['U-OSYA','U-PRIVATE'])

ch(10,'Поріг',5,'Умовне схвалення діє як спокуса продовжити випробування.','Даль вирішує побачити, що відбулося поза правильно заповненою формою.')
sc(10,7,'10:00','11:30','Квартира Едіт; дистанційний робочий виклик','Даль/Едіт/Рем','П’ятиденна проба завершується; лише попередній поріг, не поновлення житла.','Закріпити покращення до слухання.','Рем може рекомендувати поновлення лише за продовження підтримки; Едіт читає правильну відповідь замість власної.','Едіт погоджується зберегти теперішні вікна до D14, не розширювати сенсорний доступ; Даль погоджується лишитися після виклику.','Рем позначає попереднє проходження за умовами плану й чинним sponsor. Під час виклику пропонує ще одне щоденне підтвердження. Едіт майже погоджується, зупиняється й дивиться на Даля; той просить лишити наявний обсяг. Після дзвінка вона питає, яку відповідь потрібно було дати.','Результат тримається на страху втратити квартиру; Даль не може назвати цей страх виміряним бажанням.','Завтра він побачить конкретну відкладену дію, а не тільки інтонацію.','Попередня рекомендація умовна; score не гарантує автономії.','Наявна проба продовжена явно до слухання; додаткове підтвердження не ввімкнено.','P03: жива ціна успішної цифри.','Не робити з одного погляду mindreading: Едіт питає вголос, що мала відповісти.')

ch(11,'Після сигналу',5,'Ціна стає подією в конкретному дні Едіт.','Нові оптимізації припиняються, а невідкладений спір про кімнату вимагає іншого способу захисту.')
sc(11,8,'09:30','11:00','Квартира → двір','Даль/Едіт','Едіт запросила Даля перевірити форму перед власним походом на ринок. Чергове необов’язкове вікно вона сама додала, боячись зіпсувати звіт.','Даль хоче застати звичайний успішний ранок.','Вона не виходить, хоча потрібної відповіді від неї ніхто не чекає; тримає одяг на стільці до сигналу.','Разом відрізнити обов’язкове вікно від самонакладеного та припинити додавати нові правила.','Едіт показує власний список і сердито питає, чи треба все життя носити вихід у кишені до дозволу. Даль визнає, що не мав обіцяти кінець іспиту в D14. Вона прибирає своє зайве вікно й виходить; потрібний доступ майстрові не скасовує. Даль лишає спірне правило кімнати відкритим.','Частина гладких підтверджень зникне; попереднє покращення не можна видавати за стійке без умов.','Даль шукає інший легкий аргумент — характеристику від знайомого.','Джерело self-monitoring — її пояснення й список, не діагноз. Не всі обмеження накладені програмою буквально.','Необов’язкове вікно видалене власницею; базові зобов’язання зберігаються.','P03/P09: бажаний вихід відбувся, проблема житла ще ні.','Не називати разову відмову від зайвого нагадування R4; герой ще шукатиме портфоліо.')

ch(12,'Не характеристика',5,'Дружба відмовляється бути посвідченням цінності.','Замість добрих відгуків Даль запитує історію самої вимоги.')
sc(12,8,'16:00','17:15','Майстерня Тараса','Даль/Тарас/Едіт','Едіт погодилася забрати відремонтовану рамку; Тарас має наступного клієнта. Даль ще хоче довести її корисність.','Отримати підтримувальне свідчення для апеляції.','Тарас може підтвердити лише виконану роботу й конкретні домовленості, не скільки людина дає світу.','Не подавати характеристику без її волі; попросити лише точний опис виконаної ремонтної домовленості, якщо він потрібен.','Даль починає перелічувати її допомогу сусідам. Тарас повертає розмову до рамки й відмовляється підписувати паспорт хорошості. Едіт чує власне життя як список виправдань і забирає предмет сама; не приймає другого проекту порятунку. Тарас відходить до клієнта, не завершує сцену моральною лекцією.','Даль втрачає легкий аргумент і частину довіри Едіт; її дім не стане винагородою за відремонтовані речі.','Він ставить питання, хто переніс координаційний бал у право лишитися.','Наявні стосунки не підтверджують прихованої економічної вартості.','Тарас не стає безоплатною постійною підтримкою; жодної характеристики не підписано.','P06: межа доказу корисності; P05: друг має власний робочий день.','Рамка — звичайне замовлення, не секретний шедевр Едіт. Не забирати її агентність після відмови.')

ch(13,'До порога',6,'Документ випереджає героя на одну главу, не дає йому знання без читання.','Історичний пакет готовий; Даль ще не знає, яку саме зміну побачить.')
sc(13,9,'09:00','11:00','Відкрита приймальня архіву правил','Даль/Працівниця приймальні','Чинна форма вимагає поріг; Даль не має історії його появи. DOC01 читач бачить перед сценою, Даль — ні.','Отримати ланцюг версій правила.','Спочатку пошук повертає нинішню форму; потрібне окреме посилання на архівну таблицю призначень, не чужі досьє.','Запросити три публічні редакції та дати набрання чинності, без персональних записів.','Даль формулює точний запит, відкидає пропозицію завантажити весь довідник і погоджує вузьку виписку. До кінця ранку реєстрація повідомляє про готовність пакета на післяобідній перегляд. Він перевіряє склад вкладення, не читає його в черзі між чужими екранами.','Витрачає власний час і не отримує швидкої моральної характеристики для справи.','Після обіду читає ті самі версії й ставить Рему інше питання.','Даль знає тільки готовність запитаних версій. Читач через DOC01 вже бачить перенесення призначення, але не глобальну історію всього Ладу.','Публічний архів правил; нове дозволене джерело, не прихований витік.','P01/P04: purpose creep до пояснення Рема.','Не написати, що читач не має контексту. DOC01 містить тільки фрагмент документа без внутрішньої мови.')

ch(14,'Те саме число',6,'Новий факт змінює предмет спору, але не створює ресурсу.','Рем вимагає назвати конкретну ціну і джерело покриття.')
sc(14,9,'14:00','15:30','Архівний стіл → кабінет Рема','Даль/Рем','Пакет готовий; читач знає DOC01, Даль ще не відкрив.','Встановити, коли підтримку підмінили критерієм допуску.','Історія легальна й публічна, не підлог; у Рема сильний аргумент про масштаб.','Звірити версії та перестати вимагати знищення формули.','Даль читає спершу staffing/buffers, потім коротке адміністративне доповнення про поріг задля меншої кількості ручних розглядів. Рем підтверджує використання й показує список невиконаних неекстрених задач без імен. Даль визнає, що розрахунок потрібен для підтримки, але не повинен автоматично вирішувати, кому лишитися. Рем просить план витрат замість оцінки гідності.','Даль бере на себе важчу роботу: власне правильне заперечення ще нікого не оплачує.','Під тиском вартості він знову тягнеться до портфоліо Едіт.','Даль отримав той самий документальний факт, що читач у CH13; формула не доведена безпомилковою назавжди.','Архівні копії дозволені; знеособлені години без чужих медичних/житлових справ.','P01: джерело інституційного застосування; P04: опонент не бреше про дефіцит.','Не називати один policy-crosswalk таємною директивою для всього міста або всією історією Ладу.')

ch(15,'Ще може',7,'Другий продуктивістський зрив відрізняється від характеристики: Даль хоче компенсувати явні витрати майбутньою віддачею.','Заява позбавлена обіцянки окупитися; її реальна підтримка поки не оплачена.')
sc(15,10,'09:30','11:00','Квартира Едіт','Даль/Едіт','Рем назвав дефіцит; привабливих моральних свідчень немає.','Посилити пакет перед остаточним розглядом.','Даль складає колишні навички диспетчерки й можливе навчання як майбутню економію; Едіт не брала таких зобов’язань.','Прибрати портфоліо віддачі на її вимогу, не називати відмову саботажем.','Едіт викреслює зі зведення слова про повернення користі. Вона не заперечує свого минулого ремесла, але не обіцяє нового як орендної плати за життя. Даль лишає факт тривалого проживання, чинні взаємні зобов’язання і її бажання залишитися. Вона сама перевіряє версію перед збереженням.','Пакет слабший за звичною логікою; витрати не можна перекрити фантазією про неоплачену працю.','Другий заявник просить допомогти з варіантом, що не потребує такого довгого очікування.','Жоден прихований навик чи добрий вчинок не стане умовою фінальної перемоги.','Чернетку портфоліо не надіслано; її старі навчальні матеріали не стають відкритим доступом.','P06: відмова від іншого способу довести потрібність.','Не повторити слово-в-слово CH12: тут конкретний майбутній трудовий контракт, не моральний відгук.')
